import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
@interface NotNull { String message() default "must not be null"; }

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
@interface Size { int min() default 0; int max() default Integer.MAX_VALUE; String message() default "size out of range"; }

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
@interface Min { long value() default 0; String message() default "too small"; }

class User {
    @NotNull(message="username required")
    String username;
    @Size(min=6, max=20, message="password 6-20 chars")
    String password;
    @Min(18)
    int age;
    User(String u,String p,int a){username=u;password=p;age=a;}
}

public class Main {
    static List<String> validate(Object o) throws IllegalAccessException {
        List<String> errs=new ArrayList<>();
        for(Field f: o.getClass().getDeclaredFields()){
            f.setAccessible(true);
            Object v=f.get(o);
            if(f.isAnnotationPresent(NotNull.class) && v==null)
                errs.add(f.getName()+": "+f.getAnnotation(NotNull.class).message());
            if(f.isAnnotationPresent(Size.class) && v instanceof String s){
                Size sz=f.getAnnotation(Size.class);
                if(s.length()<sz.min()||s.length()>sz.max())
                    errs.add(f.getName()+": "+sz.message());
            }
            if(f.isAnnotationPresent(Min.class) && v instanceof Number n){
                Min mn=f.getAnnotation(Min.class);
                if(n.longValue()<mn.value())
                    errs.add(f.getName()+": "+mn.message());
            }
        }
        return errs;
    }
    public static void main(String[] a) throws Exception {
        User good=new User("alice","secret12",20);
        User bad=new User(null,"123",15);
        System.out.println("good violations: "+validate(good).size());
        for(String e: validate(bad)) System.out.println("BAD "+e);
    }
}
